82	const lookUpShop = async (config: E2eConfig, token: string) => {
83	  const data = await gql<{
84	    channel: { id: string };
85	    categories: { edges: { node: { id: string } }[] };
86	    promotions: { edges: { node: { id: string } }[] };
87	    warehouses: {
88	      edges: {
89	        node: {
90	          id: string;
91	          shippingZones: {
92	            edges: { node: { countries: { code: string }[]; channels: { slug: string }[] } }[];
93	          };
94	        };
95	      }[];
96	    };
97	  }>(
98	    config,
99	    `query($channel: String!) {
100	      channel(slug: $channel) { id }
101	      categories(first: 1) { edges { node { id } } }
102	      promotions(first: 100) { edges { node { id } } }
103	      warehouses(first: 100) {
104	        edges { node { id shippingZones(first: 100) { edges { node { countries { code } channels { slug } } } } } }
105	      }
106	    }`,
107	    { channel: CHANNEL.slug },
108	    token,
109	  );
110	
111	  /* Stock is only sellable through a zone that covers the address in the order's channel. */
112	  const warehouse = data.warehouses.edges.find(({ node }) =>
113	    node.shippingZones.edges.some(
