3	/**
4	 * Ported from the legacy suite. Its "welcome to your Store Dashboard" assertion was
5	 * dropped: `home-header` no longer exists anywhere in `src/` - the home page was replaced
6	 * - so that check could only ever have passed against an old dashboard.
7	 *
8	 * Signed-in is asserted on the sidebar's user menu instead. It renders only for an
9	 * authenticated user, and unlike the home page's contents it does not change with whatever
10	 * the current homepage happens to promote.
11	 */
12	export class HomePage {
13	  readonly userMenu = this.page.getByTestId("userMenu");
14	
15	  constructor(readonly page: Page) {}
16	
17	  async goto(): Promise<void> {
18	    await this.page.goto("/");
19	  }
20	
